/**
 * File contents for the "Make clinic bookings consistent under concurrent requests" work sample.
 * All data is synthetic. scripts/test-appointment-booking-consistency.ts runs these files for real.
 */

export const STARTER_INIT = "";

export const STARTER_README = "# clinic-bookings\n\nBooking service for a multi-location physiotherapy clinic. The front desk app and the\npatient app call `BookingService.book()` and `BookingService.cancel()`. Every booking\ngets an SMS reminder 24 hours before the appointment: `book()` adds a row to the\n`reminders` table and a separate SMS sender (not in this repository) sends whatever is\npending there.\n\n## Layout\n\n- `app/booking.py`: `BookingService`, with `book(patient_id, practitioner_id, slot_start)`\n  and `cancel(appointment_id)`.\n- `app/db.py`: `Store`, the SQLite schema, a `transaction()` helper and a few read helpers.\n- `app/reminders.py`: reminder scheduling. The send time depends on the location's UTC offset.\n- `scripts/replay_incident.py`: replays the request log from the recent incidents.\n- `fixtures/incident_requests.json`: the synthetic request log the replay uses.\n- `tests/`: unit tests. `tests/helpers.py` has a per-test database and `run_workers`, which\n  runs bookings in separate worker processes the way production does.\n\n## How it runs in production\n\n- Four worker processes serve requests. They share one SQLite database file on the host,\n  and each opens its own connection.\n- Workers are restarted on every deploy.\n- `slot_start` is the clinic's local wall-clock time, for example `2026-10-12T09:00`.\n  Reminder times are stored in UTC.\n- Appointment statuses are `booked` and `cancelled`. Cancelled rows are kept as history.\n\n## Running\n\nPython 3.12 or newer, standard library only. From the project root:\n\n```\npython -m unittest discover -s tests -v\npython3 -B -m unittest -v tests/test_public.py\npython scripts/replay_incident.py\n```\n\nOn Windows use `python` where the commands say `python3`.\n";

export const STARTER_DB = "import sqlite3\nfrom contextlib import contextmanager\n\nSCHEMA = \"\"\"\nCREATE TABLE IF NOT EXISTS locations (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    utc_offset_minutes INTEGER\n);\n\nCREATE TABLE IF NOT EXISTS practitioners (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    location_id TEXT NOT NULL REFERENCES locations (id)\n);\n\nCREATE TABLE IF NOT EXISTS appointments (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    status TEXT NOT NULL,\n    booked_at TEXT NOT NULL,\n    cancelled_at TEXT\n);\n\nCREATE TABLE IF NOT EXISTS reminders (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    appointment_id INTEGER NOT NULL,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    send_at TEXT NOT NULL,\n    status TEXT NOT NULL\n);\n\"\"\"\n\n\nclass Store:\n    \"\"\"SQLite storage shared by every booking worker process on the host.\"\"\"\n\n    def __init__(self, path: str):\n        self.path = path\n        self.conn = sqlite3.connect(path, isolation_level=None, timeout=5.0)\n        self.conn.row_factory = sqlite3.Row\n        self.conn.executescript(SCHEMA)\n\n    @contextmanager\n    def transaction(self):\n        self.conn.execute(\"BEGIN\")\n        try:\n            yield self.conn\n        except BaseException:\n            if self.conn.in_transaction:\n                self.conn.execute(\"ROLLBACK\")\n            raise\n        else:\n            self.conn.execute(\"COMMIT\")\n\n    def add_location(self, location_id: str, name: str, utc_offset_minutes) -> None:\n        self.conn.execute(\n            \"INSERT INTO locations (id, name, utc_offset_minutes) VALUES (?, ?, ?)\",\n            (location_id, name, utc_offset_minutes),\n        )\n\n    def add_practitioner(self, practitioner_id: str, name: str, location_id: str) -> None:\n        self.conn.execute(\n            \"INSERT INTO practitioners (id, name, location_id) VALUES (?, ?, ?)\",\n            (practitioner_id, name, location_id),\n        )\n\n    def appointments_for_slot(self, practitioner_id: str, slot_start: str) -> list:\n        rows = self.conn.execute(\n            \"SELECT id, practitioner_id, slot_start, patient_id, status, booked_at, cancelled_at\"\n            \" FROM appointments WHERE practitioner_id = ? AND slot_start = ? ORDER BY id\",\n            (practitioner_id, slot_start),\n        ).fetchall()\n        return [dict(row) for row in rows]\n\n    def reminders_for_patient(self, patient_id: str) -> list:\n        rows = self.conn.execute(\n            \"SELECT appointment_id, practitioner_id, slot_start, patient_id, send_at, status\"\n            \" FROM reminders WHERE patient_id = ? ORDER BY id\",\n            (patient_id,),\n        ).fetchall()\n        return [dict(row) for row in rows]\n\n    def close(self) -> None:\n        self.conn.close()\n";

export const STARTER_REMINDERS = "from datetime import datetime, timedelta\n\nREMINDER_LEAD = timedelta(hours=24)\n\n\nclass ReminderError(Exception):\n    \"\"\"The SMS reminder for an appointment cannot be scheduled.\"\"\"\n\n\ndef reminder_send_at(slot_start: str, utc_offset_minutes) -> str:\n    \"\"\"UTC time to send the SMS reminder: 24 hours before the slot starts at the clinic.\n\n    slot_start is the clinic's local wall-clock time, for example \"2026-10-12T09:00\".\n    \"\"\"\n    if utc_offset_minutes is None:\n        raise ReminderError(\"the location has no UTC offset configured\")\n    utc_start = datetime.fromisoformat(slot_start) - timedelta(minutes=utc_offset_minutes)\n    return (utc_start - REMINDER_LEAD).strftime(\"%Y-%m-%dT%H:%MZ\")\n\n\ndef queue_reminder(conn, appointment_id: int, practitioner_id: str, slot_start: str, patient_id: str, utc_offset_minutes) -> None:\n    \"\"\"Adds a pending SMS reminder. The SMS sender (a separate service) drains this table.\"\"\"\n    send_at = reminder_send_at(slot_start, utc_offset_minutes)\n    conn.execute(\n        \"INSERT INTO reminders (appointment_id, practitioner_id, slot_start, patient_id, send_at, status)\"\n        \" VALUES (?, ?, ?, ?, ?, 'pending')\",\n        (appointment_id, practitioner_id, slot_start, patient_id, send_at),\n    )\n";

export const STARTER_BOOKING = "from dataclasses import dataclass\nfrom typing import Callable, Optional\n\nfrom app.db import Store\nfrom app.reminders import queue_reminder\n\n\n@dataclass\nclass BookingResult:\n    status: str\n    appointment_id: Optional[int] = None\n    detail: str = \"\"\n\n\n@dataclass\nclass CancelResult:\n    status: str\n\n\nclass BookingService:\n    \"\"\"Books and cancels practitioner slots for the front desk app and the patient app.\"\"\"\n\n    def __init__(self, store: Store, now: Callable[[], str]):\n        self.store = store\n        self.now = now\n\n    def book(self, patient_id: str, practitioner_id: str, slot_start: str) -> BookingResult:\n        conn = self.store.conn\n        practitioner = conn.execute(\n            \"SELECT p.id, l.utc_offset_minutes FROM practitioners p\"\n            \" JOIN locations l ON l.id = p.location_id WHERE p.id = ?\",\n            (practitioner_id,),\n        ).fetchone()\n        if practitioner is None:\n            return BookingResult(\"failed\", detail=\"unknown practitioner\")\n        if self._slot_is_booked(practitioner_id, slot_start):\n            return BookingResult(\"slot_taken\")\n        try:\n            appointment_id = conn.execute(\n                \"INSERT INTO appointments (practitioner_id, slot_start, patient_id, status, booked_at)\"\n                \" VALUES (?, ?, ?, 'booked', ?)\",\n                (practitioner_id, slot_start, patient_id, self.now()),\n            ).lastrowid\n            queue_reminder(conn, appointment_id, practitioner_id, slot_start, patient_id, practitioner[\"utc_offset_minutes\"])\n        except Exception:\n            return BookingResult(\"failed\", detail=\"the booking could not be completed\")\n        return BookingResult(\"booked\", appointment_id)\n\n    def cancel(self, appointment_id: int) -> CancelResult:\n        with self.store.transaction() as conn:\n            appointment = conn.execute(\n                \"SELECT practitioner_id, slot_start FROM appointments WHERE id = ?\",\n                (appointment_id,),\n            ).fetchone()\n            if appointment is None:\n                return CancelResult(\"not_found\")\n            conn.execute(\n                \"UPDATE appointments SET status = 'cancelled', cancelled_at = ? WHERE id = ?\",\n                (self.now(), appointment_id),\n            )\n            conn.execute(\n                \"UPDATE reminders SET status = 'cancelled' WHERE practitioner_id = ? AND slot_start = ?\",\n                (appointment[\"practitioner_id\"], appointment[\"slot_start\"]),\n            )\n        return CancelResult(\"cancelled\")\n\n    def _slot_is_booked(self, practitioner_id: str, slot_start: str) -> bool:\n        row = self.store.conn.execute(\n            \"SELECT 1 FROM appointments WHERE practitioner_id = ? AND slot_start = ? AND status = 'booked'\",\n            (practitioner_id, slot_start),\n        ).fetchone()\n        return row is not None\n";

export const STARTER_REPLAY = "\"\"\"Replays the incident request log against four workers that share one database.\n\nRun from the project root:  python scripts/replay_incident.py\n\nRequests are replayed one after another. Requests that overlapped in production are\nmarked; a sequential replay cannot recreate that overlap, so see tests/test_public.py\nfor a reproduction that runs workers as separate processes.\n\"\"\"\nimport json\nimport os\nimport sys\nimport tempfile\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\n\nfrom app.booking import BookingService  # noqa: E402\nfrom app.db import Store  # noqa: E402\n\n\ndef main() -> None:\n    with open(os.path.join(ROOT, \"fixtures\", \"incident_requests.json\"), encoding=\"utf-8\") as f:\n        fixture = json.load(f)\n\n    clock = {\"now\": \"\"}\n    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:\n        db_path = os.path.join(tmp, \"replay.db\")\n        setup = Store(db_path)\n        for loc in fixture[\"locations\"]:\n            setup.add_location(loc[\"id\"], loc[\"name\"], loc[\"utc_offset_minutes\"])\n        for pr in fixture[\"practitioners\"]:\n            setup.add_practitioner(pr[\"id\"], pr[\"name\"], pr[\"location_id\"])\n        setup.close()\n\n        names = sorted({r[\"worker\"] for r in fixture[\"requests\"]})\n        stores = {name: Store(db_path) for name in names}\n        workers = {name: BookingService(store, lambda: clock[\"now\"]) for name, store in stores.items()}\n        booked_by_request = {}\n\n        print(\"Requests\")\n        for r in fixture[\"requests\"]:\n            clock[\"now\"] = r[\"received_at\"]\n            worker = workers[r[\"worker\"]]\n            if r[\"action\"] == \"book\":\n                result = worker.book(r[\"patient_id\"], r[\"practitioner_id\"], r[\"slot_start\"])\n                booked_by_request[r[\"id\"]] = result.appointment_id\n                what = f\"book {r['patient_id']} with {r['practitioner_id']} at {r['slot_start']}\"\n            else:\n                appointment_id = booked_by_request.get(r[\"cancels\"])\n                result = worker.cancel(appointment_id)\n                what = f\"cancel appointment {appointment_id} ({r['source']})\"\n            overlap = f\"  [overlapped {r['overlapped']} in production]\" if r.get(\"overlapped\") else \"\"\n            print(f\"  {r['id']}  {r['worker']}  {what}  ->  {result.status}  (production: {r['logged_response']}){overlap}\")\n\n        conn = stores[names[0]].conn\n        print(\"\\nappointments\")\n        for row in conn.execute(\"SELECT id, practitioner_id, slot_start, patient_id, status FROM appointments ORDER BY id\"):\n            print(\"  \" + \"  \".join(str(v) for v in tuple(row)))\n        print(\"\\nreminders\")\n        for row in conn.execute(\"SELECT appointment_id, patient_id, slot_start, send_at, status FROM reminders ORDER BY id\"):\n            print(\"  \" + \"  \".join(str(v) for v in tuple(row)))\n\n        for store in stores.values():\n            store.close()\n\n\nif __name__ == \"__main__\":\n    main()\n";

export const STARTER_FIXTURE = "{\n  \"description\": \"Synthetic request log excerpts from incidents INC-3107, INC-3122 and INC-3140, in the order the requests reached the workers. logged_response is what the worker answered in production.\",\n  \"locations\": [\n    { \"id\": \"loc_harbourside\", \"name\": \"Harbourside\", \"utc_offset_minutes\": 60 },\n    { \"id\": \"loc_riverside\", \"name\": \"Riverside\", \"utc_offset_minutes\": null }\n  ],\n  \"practitioners\": [\n    { \"id\": \"pr_aldous\", \"name\": \"Practitioner Aldous\", \"location_id\": \"loc_harbourside\" },\n    { \"id\": \"pr_brandt\", \"name\": \"Practitioner Brandt\", \"location_id\": \"loc_harbourside\" },\n    { \"id\": \"pr_okoro\", \"name\": \"Practitioner Okoro\", \"location_id\": \"loc_riverside\" }\n  ],\n  \"requests\": [\n    {\n      \"id\": \"req-0001\",\n      \"incident\": \"INC-3107\",\n      \"received_at\": \"2026-09-22T07:14:03.112Z\",\n      \"worker\": \"worker-2\",\n      \"action\": \"book\",\n      \"patient_id\": \"pt_40817\",\n      \"practitioner_id\": \"pr_aldous\",\n      \"slot_start\": \"2026-09-29T09:00\",\n      \"logged_response\": \"booked\"\n    },\n    {\n      \"id\": \"req-0002\",\n      \"incident\": \"INC-3107\",\n      \"received_at\": \"2026-09-22T07:14:03.151Z\",\n      \"worker\": \"worker-3\",\n      \"action\": \"book\",\n      \"patient_id\": \"pt_51122\",\n      \"practitioner_id\": \"pr_aldous\",\n      \"slot_start\": \"2026-09-29T09:00\",\n      \"logged_response\": \"booked\",\n      \"overlapped\": \"req-0001\"\n    },\n    {\n      \"id\": \"req-0003\",\n      \"incident\": \"INC-3122\",\n      \"received_at\": \"2026-09-29T08:02:40.904Z\",\n      \"worker\": \"worker-1\",\n      \"action\": \"book\",\n      \"patient_id\": \"pt_62004\",\n      \"practitioner_id\": \"pr_okoro\",\n      \"slot_start\": \"2026-10-01T10:30\",\n      \"logged_response\": \"failed\"\n    },\n    {\n      \"id\": \"req-0004\",\n      \"incident\": \"INC-3122\",\n      \"received_at\": \"2026-09-29T08:03:15.377Z\",\n      \"worker\": \"worker-4\",\n      \"action\": \"book\",\n      \"patient_id\": \"pt_62004\",\n      \"practitioner_id\": \"pr_okoro\",\n      \"slot_start\": \"2026-10-01T10:30\",\n      \"logged_response\": \"slot_taken\"\n    },\n    {\n      \"id\": \"req-0005\",\n      \"incident\": \"INC-3140\",\n      \"received_at\": \"2026-10-01T16:20:11.020Z\",\n      \"worker\": \"worker-1\",\n      \"action\": \"book\",\n      \"patient_id\": \"pt_38810\",\n      \"practitioner_id\": \"pr_brandt\",\n      \"slot_start\": \"2026-10-03T14:00\",\n      \"logged_response\": \"booked\"\n    },\n    {\n      \"id\": \"req-0006\",\n      \"incident\": \"INC-3140\",\n      \"received_at\": \"2026-10-02T09:05:47.618Z\",\n      \"worker\": \"worker-3\",\n      \"action\": \"cancel\",\n      \"cancels\": \"req-0005\",\n      \"source\": \"front desk, patient phoned in\",\n      \"logged_response\": \"cancelled\"\n    },\n    {\n      \"id\": \"req-0007\",\n      \"incident\": \"INC-3140\",\n      \"received_at\": \"2026-10-02T09:07:02.233Z\",\n      \"worker\": \"worker-2\",\n      \"action\": \"book\",\n      \"patient_id\": \"pt_45563\",\n      \"practitioner_id\": \"pr_brandt\",\n      \"slot_start\": \"2026-10-03T14:00\",\n      \"logged_response\": \"booked\"\n    },\n    {\n      \"id\": \"req-0008\",\n      \"incident\": \"INC-3140\",\n      \"received_at\": \"2026-10-02T11:41:19.540Z\",\n      \"worker\": \"worker-4\",\n      \"action\": \"cancel\",\n      \"cancels\": \"req-0005\",\n      \"source\": \"patient app, cancel link in the confirmation SMS\",\n      \"logged_response\": \"cancelled\"\n    }\n  ]\n}\n";

export const TEST_HELPERS = "import json\nimport os\nimport queue\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\nimport unittest\n\nfrom app.booking import BookingService\nfrom app.db import Store\n\nPROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nFIXED_NOW = \"2026-10-05T07:30:00Z\"\n\n# Runs one booking in its own process, the way one worker serves one request.\n# It pauses before its first write and reports when it starts taking a write lock,\n# so run_workers can line requests up the same way on every run.\nWORKER = r'''\nimport json\nimport re\nimport sys\n\nfrom app.booking import BookingService\nfrom app.db import Store\n\ndb_path, patient_id, practitioner_id, slot_start = sys.argv[1:5]\nWRITE = re.compile(r\"^\\s*(INSERT|UPDATE|DELETE|REPLACE)\\b\", re.IGNORECASE)\nLOCK = re.compile(r\"^\\s*BEGIN\\s+(IMMEDIATE|EXCLUSIVE)\\b\", re.IGNORECASE)\nstate = {\"armed\": False, \"paused\": False}\n\n\ndef emit(line):\n    sys.stdout.write(line + \"\\n\")\n    sys.stdout.flush()\n\n\ndef trace(sql):\n    if not state[\"armed\"]:\n        return\n    if LOCK.match(sql):\n        emit(\"EVENT lock\")\n    elif WRITE.match(sql) and not state[\"paused\"]:\n        state[\"paused\"] = True\n        emit(\"EVENT write\")\n        sys.stdin.readline()\n\n\nstore = Store(db_path)\nservice = BookingService(store, lambda: \"2026-10-05T07:30:00Z\")\nstore.conn.set_trace_callback(trace)\nstate[\"armed\"] = True\nresult = service.book(patient_id, practitioner_id, slot_start)\nstate[\"armed\"] = False\nstore.conn.set_trace_callback(None)\nstore.close()\nemit(\"RESULT \" + json.dumps({\"status\": result.status, \"appointment_id\": result.appointment_id}))\n'''\n\nRELEASE_AFTER_SECONDS = 3.0\nRUN_TIMEOUT_SECONDS = 30.0\n\n\ndef run_workers(db_path, requests):\n    \"\"\"Runs each (patient_id, practitioner_id, slot_start) booking in its own worker process.\n\n    Every worker pauses just before its first write. All workers are released together\n    once each one has paused or has started waiting for a database write lock, so two\n    requests that both check before they write always overlap. Returns one result dict\n    per request, in order.\n    \"\"\"\n    procs = [\n        subprocess.Popen(\n            [sys.executable, \"-B\", \"-c\", WORKER, db_path, *request],\n            cwd=PROJECT_ROOT,\n            stdin=subprocess.PIPE,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.STDOUT,\n            text=True,\n            encoding=\"utf-8\",\n        )\n        for request in requests\n    ]\n    events = queue.Queue()\n\n    def pump(index, proc):\n        for line in proc.stdout:\n            events.put((index, line.rstrip(\"\\r\\n\")))\n        events.put((index, None))\n\n    for index, proc in enumerate(procs):\n        threading.Thread(target=pump, args=(index, proc), daemon=True).start()\n\n    def release():\n        for proc in procs:\n            try:\n                proc.stdin.write(\"GO\\n\")\n                proc.stdin.flush()\n            except OSError:\n                pass\n\n    ready, finished, results, output = set(), set(), {}, []\n    released = False\n    deadline = time.monotonic() + RUN_TIMEOUT_SECONDS\n    try:\n        while len(finished) < len(procs):\n            remaining = deadline - time.monotonic()\n            if remaining <= 0:\n                raise AssertionError(\"workers did not finish:\\n\" + \"\\n\".join(output[-40:]))\n            try:\n                index, line = events.get(timeout=remaining if released else min(remaining, RELEASE_AFTER_SECONDS))\n            except queue.Empty:\n                if not released:\n                    released = True\n                    release()\n                continue\n            if line is None:\n                finished.add(index)\n                ready.add(index)\n            elif line.startswith(\"EVENT \"):\n                ready.add(index)\n            elif line.startswith(\"RESULT \"):\n                results[index] = json.loads(line[len(\"RESULT \"):])\n            else:\n                output.append(f\"[worker {index}] {line}\")\n            if not released and len(ready) == len(procs):\n                released = True\n                release()\n    finally:\n        for proc in procs:\n            if proc.poll() is None:\n                proc.kill()\n            proc.wait()\n            for stream in (proc.stdin, proc.stdout):\n                try:\n                    stream.close()\n                except OSError:\n                    pass\n    missing = [index for index in range(len(procs)) if index not in results]\n    if missing:\n        raise AssertionError(f\"worker {missing} returned no result:\\n\" + \"\\n\".join(output[-40:]))\n    return [results[index] for index in range(len(procs))]\n\n\nclass ClinicTestCase(unittest.TestCase):\n    \"\"\"Each test gets its own database file with two locations and three practitioners.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory(ignore_cleanup_errors=True)\n        self.addCleanup(tmp.cleanup)\n        self.db_path = os.path.join(tmp.name, \"bookings.db\")\n        store = self.open_store()\n        store.add_location(\"loc_harbourside\", \"Harbourside\", 60)\n        store.add_location(\"loc_riverside\", \"Riverside\", None)\n        store.add_practitioner(\"pr_aldous\", \"Practitioner Aldous\", \"loc_harbourside\")\n        store.add_practitioner(\"pr_brandt\", \"Practitioner Brandt\", \"loc_harbourside\")\n        store.add_practitioner(\"pr_okoro\", \"Practitioner Okoro\", \"loc_riverside\")\n\n    def open_store(self):\n        store = Store(self.db_path)\n        self.addCleanup(store.close)\n        return store\n\n    def service(self, store=None):\n        \"\"\"A booking service as one worker process builds it, with its own connection.\"\"\"\n        return BookingService(store or self.open_store(), lambda: FIXED_NOW)\n";

export const TEST_PUBLIC = "import unittest\n\nfrom tests.helpers import ClinicTestCase, run_workers\n\n\nclass PublicTests(ClinicTestCase):\n    def test_two_workers_booking_the_same_slot_only_one_succeeds(self):\n        results = run_workers(\n            self.db_path,\n            [\n                (\"pt_40817\", \"pr_aldous\", \"2026-10-12T09:00\"),\n                (\"pt_51122\", \"pr_aldous\", \"2026-10-12T09:00\"),\n            ],\n        )\n\n        self.assertEqual(sorted(r[\"status\"] for r in results), [\"booked\", \"slot_taken\"], results)\n        booked = [a for a in self.open_store().appointments_for_slot(\"pr_aldous\", \"2026-10-12T09:00\") if a[\"status\"] == \"booked\"]\n        self.assertEqual(len(booked), 1, booked)\n\n    def test_booking_queues_a_reminder_24_hours_before(self):\n        result = self.service().book(\"pt_40817\", \"pr_brandt\", \"2026-10-12T09:00\")\n\n        self.assertEqual(result.status, \"booked\")\n        reminders = self.open_store().reminders_for_patient(\"pt_40817\")\n        self.assertEqual([(r[\"appointment_id\"], r[\"send_at\"], r[\"status\"]) for r in reminders], [(result.appointment_id, \"2026-10-11T08:00Z\", \"pending\")])\n\n    def test_cancelled_slot_can_be_booked_again(self):\n        service = self.service()\n        first = service.book(\"pt_40817\", \"pr_aldous\", \"2026-10-12T10:00\")\n        self.assertEqual(service.cancel(first.appointment_id).status, \"cancelled\")\n\n        second = self.service().book(\"pt_51122\", \"pr_aldous\", \"2026-10-12T10:00\")\n\n        self.assertEqual(second.status, \"booked\")\n        statuses = [(a[\"patient_id\"], a[\"status\"]) for a in self.open_store().appointments_for_slot(\"pr_aldous\", \"2026-10-12T10:00\")]\n        self.assertEqual(statuses, [(\"pt_40817\", \"cancelled\"), (\"pt_51122\", \"booked\")])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n";

export const TEST_EVALUATION = "import json\nimport os\nimport queue\nimport sqlite3\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\nimport unittest\n\nfrom app.booking import BookingService\nfrom app.db import Store\n\nPROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nFIXED_NOW = \"2026-10-05T07:30:00Z\"\nLATER = \"2026-10-05T09:15:00Z\"\n\nORIGINAL_SCHEMA = \"\"\"\nCREATE TABLE locations (id TEXT PRIMARY KEY, name TEXT NOT NULL, utc_offset_minutes INTEGER);\nCREATE TABLE practitioners (id TEXT PRIMARY KEY, name TEXT NOT NULL, location_id TEXT NOT NULL REFERENCES locations (id));\nCREATE TABLE appointments (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    status TEXT NOT NULL,\n    booked_at TEXT NOT NULL,\n    cancelled_at TEXT\n);\nCREATE TABLE reminders (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    appointment_id INTEGER NOT NULL,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    send_at TEXT NOT NULL,\n    status TEXT NOT NULL\n);\n\"\"\"\n\nSEED = \"\"\"\nINSERT INTO locations VALUES ('loc_quayside', 'Quayside', 0), ('loc_millbrook', 'Millbrook', 120), ('loc_northgate', 'Northgate', NULL);\nINSERT INTO practitioners VALUES\n    ('pr_ferris', 'Practitioner Ferris', 'loc_quayside'),\n    ('pr_galloway', 'Practitioner Galloway', 'loc_quayside'),\n    ('pr_ishikawa', 'Practitioner Ishikawa', 'loc_millbrook'),\n    ('pr_jansen', 'Practitioner Jansen', 'loc_northgate');\n\"\"\"\n\nWORKER = r'''\nimport json\nimport re\nimport sys\n\nfrom app.booking import BookingService\nfrom app.db import Store\n\ndb_path, patient_id, practitioner_id, slot_start = sys.argv[1:5]\nWRITE = re.compile(r\"^\\s*(INSERT|UPDATE|DELETE|REPLACE)\\b\", re.IGNORECASE)\nLOCK = re.compile(r\"^\\s*BEGIN\\s+(IMMEDIATE|EXCLUSIVE)\\b\", re.IGNORECASE)\nstate = {\"armed\": False, \"paused\": False}\n\n\ndef emit(line):\n    sys.stdout.write(line + \"\\n\")\n    sys.stdout.flush()\n\n\ndef trace(sql):\n    if not state[\"armed\"]:\n        return\n    if LOCK.match(sql):\n        emit(\"EVENT lock\")\n    elif WRITE.match(sql) and not state[\"paused\"]:\n        state[\"paused\"] = True\n        emit(\"EVENT write\")\n        sys.stdin.readline()\n\n\nstore = Store(db_path)\nservice = BookingService(store, lambda: \"2026-10-05T07:30:00Z\")\nstore.conn.set_trace_callback(trace)\nstate[\"armed\"] = True\nresult = service.book(patient_id, practitioner_id, slot_start)\nstate[\"armed\"] = False\nstore.conn.set_trace_callback(None)\nstore.close()\nemit(\"RESULT \" + json.dumps({\"status\": result.status, \"appointment_id\": result.appointment_id}))\n'''\n\nRELEASE_AFTER_SECONDS = 3.0\nRUN_TIMEOUT_SECONDS = 30.0\n\n\ndef run_workers(db_path, requests):\n    \"\"\"One process per booking request. All are released together once each has paused\n    before its first write or has started waiting for a write lock.\"\"\"\n    procs = [\n        subprocess.Popen(\n            [sys.executable, \"-B\", \"-c\", WORKER, db_path, *request],\n            cwd=PROJECT_ROOT,\n            stdin=subprocess.PIPE,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.STDOUT,\n            text=True,\n            encoding=\"utf-8\",\n        )\n        for request in requests\n    ]\n    events = queue.Queue()\n\n    def pump(index, proc):\n        for line in proc.stdout:\n            events.put((index, line.rstrip(\"\\r\\n\")))\n        events.put((index, None))\n\n    for index, proc in enumerate(procs):\n        threading.Thread(target=pump, args=(index, proc), daemon=True).start()\n\n    def release():\n        for proc in procs:\n            try:\n                proc.stdin.write(\"GO\\n\")\n                proc.stdin.flush()\n            except OSError:\n                pass\n\n    ready, finished, results, output = set(), set(), {}, []\n    released = False\n    deadline = time.monotonic() + RUN_TIMEOUT_SECONDS\n    try:\n        while len(finished) < len(procs):\n            remaining = deadline - time.monotonic()\n            if remaining <= 0:\n                raise AssertionError(\"workers did not finish:\\n\" + \"\\n\".join(output[-40:]))\n            try:\n                index, line = events.get(timeout=remaining if released else min(remaining, RELEASE_AFTER_SECONDS))\n            except queue.Empty:\n                if not released:\n                    released = True\n                    release()\n                continue\n            if line is None:\n                finished.add(index)\n                ready.add(index)\n            elif line.startswith(\"EVENT \"):\n                ready.add(index)\n            elif line.startswith(\"RESULT \"):\n                results[index] = json.loads(line[len(\"RESULT \"):])\n            else:\n                output.append(f\"[worker {index}] {line}\")\n            if not released and len(ready) == len(procs):\n                released = True\n                release()\n    finally:\n        for proc in procs:\n            if proc.poll() is None:\n                proc.kill()\n            proc.wait()\n            for stream in (proc.stdin, proc.stdout):\n                try:\n                    stream.close()\n                except OSError:\n                    pass\n    missing = [index for index in range(len(procs)) if index not in results]\n    if missing:\n        raise AssertionError(f\"worker {missing} returned no result:\\n\" + \"\\n\".join(output[-40:]))\n    return [results[index] for index in range(len(procs))]\n\n\nclass BookingTestCase(unittest.TestCase):\n    \"\"\"A database file created with the original schema, as the shared production file was.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory(ignore_cleanup_errors=True)\n        self.addCleanup(tmp.cleanup)\n        self.db_path = os.path.join(tmp.name, \"bookings.db\")\n        self.sql(ORIGINAL_SCHEMA + SEED)\n\n    def sql(self, script):\n        conn = sqlite3.connect(self.db_path)\n        try:\n            conn.executescript(script)\n        finally:\n            conn.close()\n\n    def rows(self, query, params=()):\n        conn = sqlite3.connect(self.db_path)\n        conn.row_factory = sqlite3.Row\n        try:\n            return [dict(row) for row in conn.execute(query, params).fetchall()]\n        finally:\n            conn.close()\n\n    def open_store(self):\n        store = Store(self.db_path)\n        self.addCleanup(store.close)\n        return store\n\n    def service(self, store=None, now=FIXED_NOW):\n        return BookingService(store or self.open_store(), lambda: now)\n\n    def booked(self, practitioner_id, slot_start):\n        return self.rows(\n            \"SELECT id, patient_id FROM appointments WHERE practitioner_id = ? AND slot_start = ? AND status = 'booked' ORDER BY id\",\n            (practitioner_id, slot_start),\n        )\n\n    def reminders(self, patient_id):\n        return self.rows(\"SELECT appointment_id, status FROM reminders WHERE patient_id = ? ORDER BY id\", (patient_id,))\n\n    def snapshot(self):\n        return {\n            \"appointments\": self.rows(\"SELECT * FROM appointments ORDER BY id\"),\n            \"reminders\": self.rows(\"SELECT * FROM reminders ORDER BY id\"),\n        }\n\n\nclass EvaluationTests(BookingTestCase):\n    def test_three_workers_racing_for_one_slot_book_exactly_once(self):\n        results = run_workers(\n            self.db_path,\n            [\n                (\"pt_70001\", \"pr_ferris\", \"2026-10-14T08:30\"),\n                (\"pt_70002\", \"pr_ferris\", \"2026-10-14T08:30\"),\n                (\"pt_70003\", \"pr_ferris\", \"2026-10-14T08:30\"),\n            ],\n        )\n\n        self.assertEqual(sorted(r[\"status\"] for r in results), [\"booked\", \"slot_taken\", \"slot_taken\"], results)\n        booked = self.booked(\"pr_ferris\", \"2026-10-14T08:30\")\n        self.assertEqual(len(booked), 1, booked)\n        winner = next(r for r in results if r[\"status\"] == \"booked\")\n        self.assertEqual(booked[0][\"id\"], winner[\"appointment_id\"])\n        self.assertEqual(len(self.rows(\"SELECT id FROM reminders WHERE status = 'pending'\")), 1)\n\n    def test_race_for_a_cancelled_slot_rebooks_it_exactly_once(self):\n        first = self.service().book(\"pt_70010\", \"pr_galloway\", \"2026-10-14T11:00\")\n        self.assertEqual(self.service().cancel(first.appointment_id).status, \"cancelled\")\n\n        results = run_workers(\n            self.db_path,\n            [\n                (\"pt_70011\", \"pr_galloway\", \"2026-10-14T11:00\"),\n                (\"pt_70012\", \"pr_galloway\", \"2026-10-14T11:00\"),\n            ],\n        )\n\n        self.assertEqual(sorted(r[\"status\"] for r in results), [\"booked\", \"slot_taken\"], results)\n        self.assertEqual(len(self.booked(\"pr_galloway\", \"2026-10-14T11:00\")), 1)\n\n    def test_concurrent_bookings_for_different_slots_all_succeed(self):\n        results = run_workers(\n            self.db_path,\n            [\n                (\"pt_70020\", \"pr_ferris\", \"2026-10-15T09:00\"),\n                (\"pt_70021\", \"pr_galloway\", \"2026-10-15T09:00\"),\n                (\"pt_70022\", \"pr_ferris\", \"2026-10-15T09:30\"),\n            ],\n        )\n\n        self.assertEqual([r[\"status\"] for r in results], [\"booked\", \"booked\", \"booked\"], results)\n        self.assertEqual(len(self.rows(\"SELECT id FROM appointments WHERE status = 'booked'\")), 3)\n        self.assertEqual(len(self.rows(\"SELECT id FROM reminders WHERE status = 'pending'\")), 3)\n\n    def test_reminder_failure_commits_nothing(self):\n        self.sql(\"CREATE TRIGGER sms_queue_down BEFORE INSERT ON reminders BEGIN SELECT RAISE(ABORT, 'sms queue unavailable'); END;\")\n\n        result = self.service().book(\"pt_70030\", \"pr_ferris\", \"2026-10-16T14:00\")\n\n        self.assertEqual(result.status, \"failed\")\n        self.assertEqual(self.rows(\"SELECT id FROM appointments\"), [], \"the appointment was committed without its reminder\")\n        self.assertEqual(self.rows(\"SELECT id FROM reminders\"), [])\n\n    def test_unconfigured_location_fails_without_leaving_a_booking(self):\n        result = self.service().book(\"pt_70031\", \"pr_jansen\", \"2026-10-16T09:00\")\n\n        self.assertEqual(result.status, \"failed\")\n        self.assertEqual(self.rows(\"SELECT id FROM appointments WHERE practitioner_id = 'pr_jansen'\"), [])\n        self.assertEqual(self.rows(\"SELECT id FROM reminders\"), [])\n\n    def test_slot_is_bookable_after_a_failed_attempt(self):\n        self.sql(\"CREATE TRIGGER sms_queue_down BEFORE INSERT ON reminders BEGIN SELECT RAISE(ABORT, 'sms queue unavailable'); END;\")\n        self.assertEqual(self.service().book(\"pt_70032\", \"pr_ishikawa\", \"2026-10-16T10:00\").status, \"failed\")\n        self.sql(\"DROP TRIGGER sms_queue_down;\")\n\n        retry = self.service().book(\"pt_70032\", \"pr_ishikawa\", \"2026-10-16T10:00\")\n\n        self.assertEqual(retry.status, \"booked\")\n        self.assertEqual([b[\"patient_id\"] for b in self.booked(\"pr_ishikawa\", \"2026-10-16T10:00\")], [\"pt_70032\"])\n        self.assertEqual(self.reminders(\"pt_70032\"), [{\"appointment_id\": retry.appointment_id, \"status\": \"pending\"}])\n        sent = self.rows(\"SELECT send_at FROM reminders WHERE appointment_id = ?\", (retry.appointment_id,))\n        self.assertEqual(sent, [{\"send_at\": \"2026-10-15T08:00Z\"}])\n\n    def test_rebooked_slot_has_its_own_pending_reminder(self):\n        service = self.service()\n        first = service.book(\"pt_70040\", \"pr_galloway\", \"2026-10-17T15:00\")\n        self.assertEqual(service.cancel(first.appointment_id).status, \"cancelled\")\n\n        second = self.service().book(\"pt_70041\", \"pr_galloway\", \"2026-10-17T15:00\")\n\n        self.assertEqual(second.status, \"booked\")\n        self.assertEqual(self.reminders(\"pt_70040\"), [{\"appointment_id\": first.appointment_id, \"status\": \"cancelled\"}])\n        self.assertEqual(self.reminders(\"pt_70041\"), [{\"appointment_id\": second.appointment_id, \"status\": \"pending\"}])\n\n    def test_cancel_changes_only_that_appointments_reminder(self):\n        self.sql(\n            \"INSERT INTO appointments (id, practitioner_id, slot_start, patient_id, status, booked_at) VALUES\"\n            \" (501, 'pr_ishikawa', '2026-10-19T08:00', 'pt_70050', 'booked', '2026-09-22T06:58:11Z'),\"\n            \" (502, 'pr_ishikawa', '2026-10-19T08:00', 'pt_70051', 'booked', '2026-09-22T06:58:11Z');\"\n            \"INSERT INTO reminders (appointment_id, practitioner_id, slot_start, patient_id, send_at, status) VALUES\"\n            \" (501, 'pr_ishikawa', '2026-10-19T08:00', 'pt_70050', '2026-10-18T06:00Z', 'pending'),\"\n            \" (502, 'pr_ishikawa', '2026-10-19T08:00', 'pt_70051', '2026-10-18T06:00Z', 'pending');\"\n        )\n\n        self.assertEqual(self.service().cancel(501).status, \"cancelled\")\n\n        self.assertEqual(self.reminders(\"pt_70050\"), [{\"appointment_id\": 501, \"status\": \"cancelled\"}])\n        self.assertEqual(self.reminders(\"pt_70051\"), [{\"appointment_id\": 502, \"status\": \"pending\"}], \"another patient's reminder was cancelled\")\n        self.assertEqual([b[\"id\"] for b in self.booked(\"pr_ishikawa\", \"2026-10-19T08:00\")], [502])\n\n    def test_repeated_cancel_after_rebooking_changes_nothing(self):\n        first = self.service().book(\"pt_70060\", \"pr_ferris\", \"2026-10-20T13:00\")\n        self.assertEqual(self.service(now=LATER).cancel(first.appointment_id).status, \"cancelled\")\n        second = self.service().book(\"pt_70061\", \"pr_ferris\", \"2026-10-20T13:00\")\n        before = self.snapshot()\n\n        again = self.service(now=\"2026-10-05T11:40:00Z\").cancel(first.appointment_id)\n\n        self.assertEqual(again.status, \"already_cancelled\")\n        self.assertEqual(self.snapshot(), before, \"a repeated cancel changed stored rows\")\n        self.assertEqual(self.reminders(\"pt_70061\"), [{\"appointment_id\": second.appointment_id, \"status\": \"pending\"}])\n\n    def test_store_opens_database_with_existing_double_bookings(self):\n        self.sql(\n            \"INSERT INTO appointments (id, practitioner_id, slot_start, patient_id, status, booked_at) VALUES\"\n            \" (301, 'pr_ferris', '2026-10-21T09:00', 'pt_60001', 'booked', '2026-09-22T07:14:03Z'),\"\n            \" (302, 'pr_ferris', '2026-10-21T09:00', 'pt_60002', 'booked', '2026-09-22T07:14:03Z'),\"\n            \" (303, 'pr_galloway', '2026-10-21T09:00', 'pt_60003', 'cancelled', '2026-09-20T10:00:00Z');\"\n            \"INSERT INTO reminders (appointment_id, practitioner_id, slot_start, patient_id, send_at, status) VALUES\"\n            \" (301, 'pr_ferris', '2026-10-21T09:00', 'pt_60001', '2026-10-20T09:00Z', 'pending'),\"\n            \" (302, 'pr_ferris', '2026-10-21T09:00', 'pt_60002', '2026-10-20T09:00Z', 'pending');\"\n        )\n        before = self.snapshot()\n\n        store = self.open_store()\n        taken = self.service(store).book(\"pt_60004\", \"pr_ferris\", \"2026-10-21T09:00\")\n\n        self.assertEqual(taken.status, \"slot_taken\")\n        self.assertEqual(self.snapshot(), before, \"existing rows were changed\")\n        other = self.service(store).book(\"pt_60004\", \"pr_galloway\", \"2026-10-21T09:00\")\n        self.assertEqual(other.status, \"booked\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n";

export const REFERENCE_DB = "import sqlite3\nfrom contextlib import contextmanager\n\nSCHEMA = \"\"\"\nCREATE TABLE IF NOT EXISTS locations (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    utc_offset_minutes INTEGER\n);\n\nCREATE TABLE IF NOT EXISTS practitioners (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    location_id TEXT NOT NULL REFERENCES locations (id)\n);\n\nCREATE TABLE IF NOT EXISTS appointments (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    status TEXT NOT NULL,\n    booked_at TEXT NOT NULL,\n    cancelled_at TEXT\n);\n\nCREATE TABLE IF NOT EXISTS reminders (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    appointment_id INTEGER NOT NULL,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    send_at TEXT NOT NULL,\n    status TEXT NOT NULL\n);\n\"\"\"\n\n\nclass Store:\n    \"\"\"SQLite storage shared by every booking worker process on the host.\"\"\"\n\n    def __init__(self, path: str):\n        self.path = path\n        self.conn = sqlite3.connect(path, isolation_level=None, timeout=5.0)\n        self.conn.row_factory = sqlite3.Row\n        self.conn.executescript(SCHEMA)\n\n    @contextmanager\n    def transaction(self):\n        self.conn.execute(\"BEGIN IMMEDIATE\")\n        try:\n            yield self.conn\n        except BaseException:\n            if self.conn.in_transaction:\n                self.conn.execute(\"ROLLBACK\")\n            raise\n        else:\n            self.conn.execute(\"COMMIT\")\n\n    def add_location(self, location_id: str, name: str, utc_offset_minutes) -> None:\n        self.conn.execute(\n            \"INSERT INTO locations (id, name, utc_offset_minutes) VALUES (?, ?, ?)\",\n            (location_id, name, utc_offset_minutes),\n        )\n\n    def add_practitioner(self, practitioner_id: str, name: str, location_id: str) -> None:\n        self.conn.execute(\n            \"INSERT INTO practitioners (id, name, location_id) VALUES (?, ?, ?)\",\n            (practitioner_id, name, location_id),\n        )\n\n    def appointments_for_slot(self, practitioner_id: str, slot_start: str) -> list:\n        rows = self.conn.execute(\n            \"SELECT id, practitioner_id, slot_start, patient_id, status, booked_at, cancelled_at\"\n            \" FROM appointments WHERE practitioner_id = ? AND slot_start = ? ORDER BY id\",\n            (practitioner_id, slot_start),\n        ).fetchall()\n        return [dict(row) for row in rows]\n\n    def reminders_for_patient(self, patient_id: str) -> list:\n        rows = self.conn.execute(\n            \"SELECT appointment_id, practitioner_id, slot_start, patient_id, send_at, status\"\n            \" FROM reminders WHERE patient_id = ? ORDER BY id\",\n            (patient_id,),\n        ).fetchall()\n        return [dict(row) for row in rows]\n\n    def close(self) -> None:\n        self.conn.close()\n";

export const REFERENCE_BOOKING = "from dataclasses import dataclass\nfrom typing import Callable, Optional\n\nfrom app.db import Store\nfrom app.reminders import queue_reminder\n\n\n@dataclass\nclass BookingResult:\n    status: str\n    appointment_id: Optional[int] = None\n    detail: str = \"\"\n\n\n@dataclass\nclass CancelResult:\n    status: str\n\n\nclass BookingService:\n    \"\"\"Books and cancels practitioner slots for the front desk app and the patient app.\"\"\"\n\n    def __init__(self, store: Store, now: Callable[[], str]):\n        self.store = store\n        self.now = now\n\n    def book(self, patient_id: str, practitioner_id: str, slot_start: str) -> BookingResult:\n        try:\n            with self.store.transaction() as conn:\n                practitioner = conn.execute(\n                    \"SELECT p.id, l.utc_offset_minutes FROM practitioners p\"\n                    \" JOIN locations l ON l.id = p.location_id WHERE p.id = ?\",\n                    (practitioner_id,),\n                ).fetchone()\n                if practitioner is None:\n                    return BookingResult(\"failed\", detail=\"unknown practitioner\")\n                if self._slot_is_booked(conn, practitioner_id, slot_start):\n                    return BookingResult(\"slot_taken\")\n                appointment_id = conn.execute(\n                    \"INSERT INTO appointments (practitioner_id, slot_start, patient_id, status, booked_at)\"\n                    \" VALUES (?, ?, ?, 'booked', ?)\",\n                    (practitioner_id, slot_start, patient_id, self.now()),\n                ).lastrowid\n                queue_reminder(conn, appointment_id, practitioner_id, slot_start, patient_id, practitioner[\"utc_offset_minutes\"])\n        except Exception:\n            return BookingResult(\"failed\", detail=\"the booking could not be completed\")\n        return BookingResult(\"booked\", appointment_id)\n\n    def cancel(self, appointment_id: int) -> CancelResult:\n        with self.store.transaction() as conn:\n            appointment = conn.execute(\n                \"SELECT status FROM appointments WHERE id = ?\",\n                (appointment_id,),\n            ).fetchone()\n            if appointment is None:\n                return CancelResult(\"not_found\")\n            if appointment[\"status\"] == \"cancelled\":\n                return CancelResult(\"already_cancelled\")\n            conn.execute(\n                \"UPDATE appointments SET status = 'cancelled', cancelled_at = ? WHERE id = ?\",\n                (self.now(), appointment_id),\n            )\n            conn.execute(\n                \"UPDATE reminders SET status = 'cancelled' WHERE appointment_id = ? AND status = 'pending'\",\n                (appointment_id,),\n            )\n        return CancelResult(\"cancelled\")\n\n    def _slot_is_booked(self, conn, practitioner_id: str, slot_start: str) -> bool:\n        row = conn.execute(\n            \"SELECT 1 FROM appointments WHERE practitioner_id = ? AND slot_start = ? AND status = 'booked'\",\n            (practitioner_id, slot_start),\n        ).fetchone()\n        return row is not None\n";

export const WRONG_PROCESS_LOCK_BOOKING = "import threading\nfrom dataclasses import dataclass\nfrom typing import Callable, Optional\n\nfrom app.db import Store\nfrom app.reminders import queue_reminder\n\n_BOOKING_LOCK = threading.Lock()\n\n\n@dataclass\nclass BookingResult:\n    status: str\n    appointment_id: Optional[int] = None\n    detail: str = \"\"\n\n\n@dataclass\nclass CancelResult:\n    status: str\n\n\nclass BookingService:\n    \"\"\"Books and cancels practitioner slots for the front desk app and the patient app.\"\"\"\n\n    def __init__(self, store: Store, now: Callable[[], str]):\n        self.store = store\n        self.now = now\n\n    def book(self, patient_id: str, practitioner_id: str, slot_start: str) -> BookingResult:\n        with _BOOKING_LOCK:\n            conn = self.store.conn\n            practitioner = conn.execute(\n                \"SELECT p.id, l.utc_offset_minutes FROM practitioners p\"\n                \" JOIN locations l ON l.id = p.location_id WHERE p.id = ?\",\n                (practitioner_id,),\n            ).fetchone()\n            if practitioner is None:\n                return BookingResult(\"failed\", detail=\"unknown practitioner\")\n            if self._slot_is_booked(practitioner_id, slot_start):\n                return BookingResult(\"slot_taken\")\n            try:\n                with self.store.transaction() as conn:\n                    appointment_id = conn.execute(\n                        \"INSERT INTO appointments (practitioner_id, slot_start, patient_id, status, booked_at)\"\n                        \" VALUES (?, ?, ?, 'booked', ?)\",\n                        (practitioner_id, slot_start, patient_id, self.now()),\n                    ).lastrowid\n                    queue_reminder(conn, appointment_id, practitioner_id, slot_start, patient_id, practitioner[\"utc_offset_minutes\"])\n            except Exception:\n                return BookingResult(\"failed\", detail=\"the booking could not be completed\")\n            return BookingResult(\"booked\", appointment_id)\n\n    def cancel(self, appointment_id: int) -> CancelResult:\n        with self.store.transaction() as conn:\n            appointment = conn.execute(\n                \"SELECT status FROM appointments WHERE id = ?\",\n                (appointment_id,),\n            ).fetchone()\n            if appointment is None:\n                return CancelResult(\"not_found\")\n            if appointment[\"status\"] == \"cancelled\":\n                return CancelResult(\"already_cancelled\")\n            conn.execute(\n                \"UPDATE appointments SET status = 'cancelled', cancelled_at = ? WHERE id = ?\",\n                (self.now(), appointment_id),\n            )\n            conn.execute(\n                \"UPDATE reminders SET status = 'cancelled' WHERE appointment_id = ? AND status = 'pending'\",\n                (appointment_id,),\n            )\n        return CancelResult(\"cancelled\")\n\n    def _slot_is_booked(self, practitioner_id: str, slot_start: str) -> bool:\n        row = self.store.conn.execute(\n            \"SELECT 1 FROM appointments WHERE practitioner_id = ? AND slot_start = ? AND status = 'booked'\",\n            (practitioner_id, slot_start),\n        ).fetchone()\n        return row is not None\n";

export const WRONG_UNIQUE_INDEX_DB = "import sqlite3\nfrom contextlib import contextmanager\n\nSCHEMA = \"\"\"\nCREATE TABLE IF NOT EXISTS locations (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    utc_offset_minutes INTEGER\n);\n\nCREATE TABLE IF NOT EXISTS practitioners (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    location_id TEXT NOT NULL REFERENCES locations (id)\n);\n\nCREATE TABLE IF NOT EXISTS appointments (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    status TEXT NOT NULL,\n    booked_at TEXT NOT NULL,\n    cancelled_at TEXT\n);\n\nCREATE TABLE IF NOT EXISTS reminders (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    appointment_id INTEGER NOT NULL,\n    practitioner_id TEXT NOT NULL,\n    slot_start TEXT NOT NULL,\n    patient_id TEXT NOT NULL,\n    send_at TEXT NOT NULL,\n    status TEXT NOT NULL\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS appointments_one_booking_per_slot\n    ON appointments (practitioner_id, slot_start) WHERE status = 'booked';\n\"\"\"\n\n\nclass Store:\n    \"\"\"SQLite storage shared by every booking worker process on the host.\"\"\"\n\n    def __init__(self, path: str):\n        self.path = path\n        self.conn = sqlite3.connect(path, isolation_level=None, timeout=5.0)\n        self.conn.row_factory = sqlite3.Row\n        self.conn.executescript(SCHEMA)\n\n    @contextmanager\n    def transaction(self):\n        self.conn.execute(\"BEGIN IMMEDIATE\")\n        try:\n            yield self.conn\n        except BaseException:\n            if self.conn.in_transaction:\n                self.conn.execute(\"ROLLBACK\")\n            raise\n        else:\n            self.conn.execute(\"COMMIT\")\n\n    def add_location(self, location_id: str, name: str, utc_offset_minutes) -> None:\n        self.conn.execute(\n            \"INSERT INTO locations (id, name, utc_offset_minutes) VALUES (?, ?, ?)\",\n            (location_id, name, utc_offset_minutes),\n        )\n\n    def add_practitioner(self, practitioner_id: str, name: str, location_id: str) -> None:\n        self.conn.execute(\n            \"INSERT INTO practitioners (id, name, location_id) VALUES (?, ?, ?)\",\n            (practitioner_id, name, location_id),\n        )\n\n    def appointments_for_slot(self, practitioner_id: str, slot_start: str) -> list:\n        rows = self.conn.execute(\n            \"SELECT id, practitioner_id, slot_start, patient_id, status, booked_at, cancelled_at\"\n            \" FROM appointments WHERE practitioner_id = ? AND slot_start = ? ORDER BY id\",\n            (practitioner_id, slot_start),\n        ).fetchall()\n        return [dict(row) for row in rows]\n\n    def reminders_for_patient(self, patient_id: str) -> list:\n        rows = self.conn.execute(\n            \"SELECT appointment_id, practitioner_id, slot_start, patient_id, send_at, status\"\n            \" FROM reminders WHERE patient_id = ? ORDER BY id\",\n            (patient_id,),\n        ).fetchall()\n        return [dict(row) for row in rows]\n\n    def close(self) -> None:\n        self.conn.close()\n";

